package com.yeyamo_mobile.api.admin_service.service;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.security.access.AccessDeniedException;import com.yeyamo_mobile.api.admin_service.models.AdminScope;import com.yeyamo_mobile.api.admin_service.repository.AdminScopeRepository;
@Service public class AdminScopeService {private final AdminScopeRepository scopes;public AdminScopeService(AdminScopeRepository s){scopes=s;}public List<AdminScope> forAdmin(UUID id){return scopes.findByAdminUserId(id);}public void requireCountry(UUID admin,boolean superAdmin,String country){if(superAdmin)return;var all=forAdmin(admin);boolean allowed=all.stream().anyMatch(s->s.scopeType==AdminScope.Type.GLOBAL||(country!=null&&country.equalsIgnoreCase(s.countryCode)));if(!allowed)throw new AccessDeniedException("Target country is outside administrator scope");}}
